// ---------- dile göre küme ----------
// Kitabın dili kümenin anahtarıdır; aşağıda kitaba "dil" alanı olarak da yazılır (okuma.js KITAP.dil: lang niteliği,
// sesli okuma ve çeviri onu dil tahmininin önüne koyar).
export const ORNEK_KITAPLAR = {
  tr: { kagit: KAGIT, sucveceza: SUC, donusum: DONUSUM },
  en: { kagit: KAGIT_EN, sucveceza: SUC_EN, donusum: DONUSUM_EN },
};
for (const [d, k] of Object.entries(ORNEK_KITAPLAR)) for (const kitap of Object.values(k)) kitap.dil = d;
const gecerliDil = (d) => typeof d === "string" && Object.hasOwn(ORNEK_KITAPLAR, d);
const kume = (dil) => ORNEK_KITAPLAR[dil] || ORNEK_KITAPLAR.tr;
const kitapAl = (id, dil) => kume(dil)[id] || ORNEK_KITAPLAR.tr[id] || null;

// Örneğin içerik dili. Dil değişince metin değişirse kayıtlı vurgular ve notlar kayar; bu yüzden kitaplık kaydı
// kendi dilini "ornekDil" alanında taşır (ornekKunye kayıt kurulurken yazar, ornekKunyeDile açılışta düzeltir).
// Alanı olmayan kayıt bu alandan önce, yalnız Türkçe varken kurulmuştur: "tr". Kimlikle (kayıtsız) soran arayüz dilini alır.
export function ornekDili(belge) {
  if (belge && typeof belge === "object") return gecerliDil(belge.ornekDil) ? belge.ornekDil : "tr";
  return gecerliDil(arayuzDili) ? arayuzDili : "tr";
}

// Kaydın kendi örnek kimliği: çoğaltılmış örnekte kaynağınki (ornekAsil), yoksa kendi kimliği
const kendiKimlik = (belge) => typeof belge === "string" ? belge : belge?.ornekAsil || belge?.id;
// Okunacak örnek kitap. belge: kitaplık kaydı ya da kimlik. Eski sürümde ortak denemenin üstüne not alınmış örnek
// (app.js veri.ornekMetin = "kagit" ile işaretler) notları kaymasın diye o metinde kalır. Bilinmeyen kimlik
// (3. sürümden önce çoğaltılmış örnek: o zaman bütün örnekler denemeyi açıyordu): deneme.
// dil verilmezse kaydın içerik dili (ornekDili); arayüz dili verilmemeli, yoksa eski notlar kayar.
export function ornekKitap(belge, dil = ornekDili(belge)) {
  const id = typeof belge === "string" ? belge : belge?.veri?.ornekMetin || kendiKimlik(belge);
  return kitapAl(id, dil) || kitapAl("kagit", dil);
}
export const ornekKendiMetni = (belge) => ornekKitap(belge).id === kendiKimlik(belge);
// Kitaplık künyesi: { ad, yazar, ornekDil }. ornekDil yeni kaydın içerik dilidir (ortak.js künyeyi kayda yayar).
export function ornekKunye(id, dil = ornekDili(id)) {
  const k = kitapAl(id, dil);
  return k ? { ...k.kitaplik, ornekDil: k.dil } : null;
}
// Kayıtlı örnek dile çekilir. Hiç açılmamış örnek (verisi yok) arayüz diline geçer; açılmış olan notları kaymasın diye
// kendi içerik dilinde kalır. Sonra künye içerik diline çekilir: ad ya da yazar hâlâ bir dildeki örnek künyesiyse
// (kullanıcı değiştirmediyse) değişir, kullanıcı başka bir ad verdiyse dokunulmaz. Belge verisi yüklenmiş olmalı
// (app.js veriBekle'den sonra çağırır). Dönen: değişti mi. İkinci argüman yok sayılır: app.js eskiden "tr" sabitini
// verirdi, uyulsa İngilizce cihazda açılmamış örnekler her açılışta Türkçeye dönerdi.
export function ornekKunyeDile(belge) {
  const dil = arayuzDili;
  if (!belge || belge.dosya || typeof belge !== "object" || !kitapAl(belge.id, "tr")) return false;
  let degisti = false;
  const icerik = belge.veri == null && gecerliDil(dil) ? dil : ornekDili(belge);
  if (belge.ornekDil !== icerik) { belge.ornekDil = icerik; degisti = true; }
  const yeni = ornekKunye(belge.id, icerik);
  const tum = Object.values(ORNEK_KITAPLAR).map((k) => k[belge.id]?.kitaplik).filter(Boolean);
  for (const a of ["ad", "yazar"]) {
    if (belge[a] === yeni[a] || !tum.some((k) => k[a] === belge[a])) continue;
    belge[a] = yeni[a];
    degisti = true;
  }
  return degisti;
}
// Arama dizini imzası: kitap ya da metni değişince örnek yeniden dizinlenir
const imzalar = new WeakMap();
export function ornekKitapImza(belge, dil = ornekDili(belge)) {
  const k = ornekKitap(belge, dil);
  if (!imzalar.has(k)) {
    let n = 0, boy = 0;
    for (const b of k.bolumler) for (const p of b.paragraflar) { n++; boy += p.length; }
    imzalar.set(k, `${k.id}.${k.bolumler.length}.${n}.${boy}`);
  }
  return `${dil}.${imzalar.get(k)}`;
}

// Aranan sözcüğün geçtiği ilk paragrafın sanal sayfası (okuma.js: kart sayfası paragrafın başladığı sayfadır).
// Sayım okuma.js modeliKur ile aynı: sahne ayracı ve boş paragraf sayılmaz. Bulunamazsa 0.
const kelimeSay = (s) => (s.match(/\S+/g) || []).length;
export function ornekSayfa(kitap, aranan) {
  // Küçük harf kitabın kendi diliyle: Türkçe kural İngilizce "I"yı "ı" yapardı
  const yer = kitap?.dil || "tr";
  const q = String(aranan || "").toLocaleLowerCase(yer);
  if (!kitap || !q) return 0;
  let onceki = 0;
  for (const b of kitap.bolumler) {
    for (const p of b.paragraflar) {
      if (p === SAHNE || !p.trim()) continue;
      if (p.toLocaleLowerCase(yer).includes(q)) return Math.floor(onceki / SAYFA_KELIME) + 1;
      onceki += kelimeSay(p);
    }
  }
  return 0;
}
// Kitabın örnek kelime kartları; sayfa okunan metinden (eski kayıtta denemeye bağlı kalan örnekte bulunamazsa 1)
export function ornekKitapKartlari(belge, dil = ornekDili(belge)) {
  const tanim = kitapAl(kendiKimlik(belge), dil)?.kartlar || [];
  const okunan = ornekKitap(belge, dil);
  return tanim.map((k) => ({ on: k.on, arka: k.arka, sayfa: ornekSayfa(okunan, k.aranan) || 1 }));
}

// Eski içe aktarımlar için: varsayılan dışa aktarım deneme ("Kâğıdın Hafızası")
export default KAGIT;
